// Generated by Plot.

import { IncomingMessage, ServerResponse } from "node:http"
import { Socket } from "node:net"
import { afterEach, expect, it, vi } from "vitest"
import { consolePipeHeartbeatMiddleware } from "./vite-console-heartbeat.ts"

afterEach(() => {
  vi.restoreAllMocks()
  vi.useRealTimers()
})

function stream(url: string) {
  const request = new IncomingMessage(new Socket())
  request.url = url
  const response = new ServerResponse(request)
  response.setHeader("Content-Type", "text/event-stream")
  vi.spyOn(response, "headersSent", "get").mockReturnValue(true)
  const write = vi.spyOn(response, "write").mockReturnValue(true)
  const next = vi.fn()
  consolePipeHeartbeatMiddleware(request, response, next)
  expect(next).toHaveBeenCalledOnce()
  return { response, write }
}

it("keeps the idle console stream active beyond a minute and releases its timer on disconnect", () => {
  vi.useFakeTimers()
  const { response, write } = stream("/__tsd/console-pipe/sse")
  vi.advanceTimersByTime(75_000)
  expect(write.mock.calls.map(([data]) => data)).toEqual(Array(5).fill(": heartbeat\n\n"))
  response.emit("close")
  vi.advanceTimersByTime(60_000)
  expect(write).toHaveBeenCalledTimes(5)
  expect(vi.getTimerCount()).toBe(0)
})

it("does not write before the SSE headers or into other responses", () => {
  vi.useFakeTimers()
  const { response, write } = stream("/__tsd/console-pipe/sse")
  vi.spyOn(response, "headersSent", "get").mockReturnValue(false)
  vi.advanceTimersByTime(15_000)
  expect(write).not.toHaveBeenCalled()
  vi.spyOn(response, "headersSent", "get").mockReturnValue(true)
  response.setHeader("Content-Type", "text/html")
  vi.advanceTimersByTime(15_000)
  expect(write).not.toHaveBeenCalled()
  response.emit("finish")
  expect(vi.getTimerCount()).toBe(0)
  const other = stream("/api/checkStatus")
  vi.advanceTimersByTime(60_000)
  expect(other.write).not.toHaveBeenCalled()
  expect(vi.getTimerCount()).toBe(0)
})
